		{
			for (ClanMember m : members)
			{
				if (m.getName().equals(name))
				{
					return m;
				}
			}
			return null;
		}

		@Override
		public ClanTitle titleForRank(ClanRank rank)
		{
			String t = titles.get(rank.getRank());
