		click(panel, "Join the stream voice channel");
		assertEquals("open https://discord.com/channels/1/2", calls.log.get(calls.log.size() - 1));
		click(panel, "Leave");
		assertEquals("liveLeave", calls.log.get(calls.log.size() - 1));
	}

